// Run by Electron, exercising the bundled production window and isolated preload.
const { app, BrowserWindow, screen } = require('electron')
const assert = require('node:assert/strict')
const { writeFile } = require('node:fs/promises')
const { pathToFileURL } = require('node:url')
const path = require('node:path')
const { mkdtempSync, readFileSync, writeFileSync } = require('node:fs')
const { tmpdir } = require('node:os')
const testDirectory = mkdtempSync(path.join(tmpdir(), 'dsh-jingle-notch-smoke-'))
app.setPath('appData', testDirectory)
app.setPath('userData', path.join(testDirectory, 'dsh-jingle-notch'))
const pointerPath = path.join(testDirectory, 'pointer.json')
writeFileSync(pointerPath, JSON.stringify({ x:-10000, y:-10000 }))
app.once('ready', () => { screen.getCursorScreenPoint = () => JSON.parse(readFileSync(pointerPath, 'utf8')) })
const pause = ms => new Promise(resolve=>setTimeout(resolve,ms))
let done=false, attached=false
const deadline=setTimeout(()=>{console.error('SMOKE FAILED: deadline');app.exit(1)},60000)
app.on('browser-window-created',(_event,win)=>{
 if(attached)return;attached=true
 let nativeLevel
 const setLevel=win.setAlwaysOnTop.bind(win)
 win.setAlwaysOnTop=(flag,level,...rest)=>{nativeLevel=level;return setLevel(flag,level,...rest)}
 win.webContents.on('console-message',event=>{if(event.level==='error')console.error('RENDERER',event.message)})
 win.webContents.once('did-finish-load',async()=>{
  try{
   const js=source=>win.webContents.executeJavaScript(source,true)
   for(let i=0;i<100;i++){
    if(await js("document.querySelectorAll('#cards form').length === 1"))break
    await pause(100)
   }
   assert.equal(await js("typeof require + ':' + typeof process"),'undefined:undefined')
   assert.equal(await js("document.body.dataset.mode"),'expanded','New actionable requests should open the overview without hover')
   assert.equal(await js("document.querySelector('.session-chip[aria-pressed=true]').dataset.id"),'smoke')
   assert.equal(await js("document.getElementById('focus-name').textContent"),'companion')
   await js("window.jingleNotch.expand(false)")
   await pause(1100)
   assert.equal(await js("document.body.dataset.mode"),'compact','Repeated polls should leave an explicitly collapsed request closed')
   win.webContents.debugger.attach('1.3')
   const motion=async value=>{
    await win.webContents.debugger.sendCommand('Emulation.setEmulatedMedia',{features:[{name:'prefers-reduced-motion',value}]})
    for(let i=0;i<60;i++){
     const ready=await js(`matchMedia('(prefers-reduced-motion:reduce)').matches===${value==='reduce'}&&Array.from(document.querySelectorAll('.whale-raster')).every(image=>image.currentSrc.endsWith('-poster.webp')===${value==='reduce'})`)
     if(ready){await js("Promise.all(Array.from(document.querySelectorAll('.whale-raster'), image=>image.decode())).then(()=>true)");return}
     await pause(50)
    }
    throw new Error(`Whale images did not select the ${value} artwork`)
   }
   await motion('no-preference')
   assert.equal(await js("Array.from(document.querySelectorAll('.whale-raster')).every(image=>image.complete&&image.naturalWidth>0&&!image.dataset.failed)"),true,'All packaged whale images should decode without a fallback')
   assert.equal(await js("document.getElementById('mascot-avatar').dataset.state"),'attention','Pending questions should take priority at the notch')
   const screenshot=process.env.JINGLE_NOTCH_SMOKE_SCREENSHOT || '/tmp/dsh-jingle-notch-overlay-smoke.png'
   // Freeze CSS motion so different captured pixels prove the WebP itself is animated.
   await js("var proofStyle=document.createElement('style');proofStyle.id='animation-proof';proofStyle.textContent='.whale-avatar{animation:none!important;transform:none!important;filter:none!important}';document.head.appendChild(proofStyle)")
   const verifyAnimation=async(selector,name)=>{
    const rect=await js(`(()=>{const r=document.querySelector(${JSON.stringify(selector)}).getBoundingClientRect();return{x:Math.floor(r.x),y:Math.floor(r.y),width:Math.ceil(r.width),height:Math.ceil(r.height)}})()`)
    const frames=new Set()
    for(let i=0;i<7;i++){
     await pause(140)
     const frame=await win.webContents.capturePage(rect)
     frames.add(frame.toBitmap().toString('base64'))
     await writeFile(screenshot.replace(/\.png$/u,`-${name}-${i}.png`),frame.toPNG())
    }
    assert.ok(frames.size>1,`${name} should show changing WebP pixels with CSS animation disabled`)
    return frames.size
   }
   const notchFrames=await verifyAnimation('#mascot-avatar','notch')
   const secondaryFrames=await verifyAnimation('#secondary-avatar','secondary')
   assert.notEqual(await js("document.getElementById('mascot-avatar').dataset.state"),await js("document.getElementById('secondary-avatar').dataset.state"),'The two compact wings should use different whale variants')
   await writeFile(screenshot.replace(/\.png$/u,'-compact.png'),(await win.webContents.capturePage()).toPNG())
   const display=screen.getPrimaryDisplay().bounds
   await writeFile(pointerPath,JSON.stringify({x:display.x+Math.round(display.width/2),y:display.y+10}))
   for(let i=0;i<40;i++){if(await js("document.body.dataset.mode==='expanded'"))break;await pause(50)}
   assert.equal(await js("document.body.dataset.mode"),'expanded','Hovering the notch should open the overview')
   assert.ok(win.getBounds().height<280,'Session overview should remain shallow')
   await pause(300)
   const overviewShot=await win.webContents.capturePage()
   await writeFile(screenshot.replace(/\.png$/u,'-overview.png'),overviewShot.toPNG())
   const gridMetrics=await js("(()=>{var g=document.getElementById('session-grid'),r=g.getBoundingClientRect();return{height:g.clientHeight,total:g.scrollHeight,visible:Array.from(g.children).filter(n=>{var p=n.getBoundingClientRect();return p.top>=r.top-.5&&p.bottom<=r.bottom+.5}).length,colors:Array.from(g.children,n=>getComputedStyle(n).borderTopColor)}})()")
   assert.equal(gridMetrics.height,77)
   assert.equal(gridMetrics.visible,4,'Only four complete session pills should be visible')
   assert.ok(gridMetrics.total>gridMetrics.height,'Additional sessions should overflow inside the list')
   assert.equal(new Set(gridMetrics.colors).size,8,'Each fixture session should have a different border color')
   const wheelPoint=await js("(()=>{var r=document.getElementById('session-grid').getBoundingClientRect();return{x:Math.round(r.x+r.width/2),y:Math.round(r.y+r.height/2)}})()")
   win.webContents.sendInputEvent({type:'mouseWheel',...wheelPoint,deltaX:0,deltaY:-160,canScroll:true})
   await pause(250)
   assert.ok(await js("document.getElementById('session-grid').scrollTop")>0,'A real renderer wheel event should reveal later sessions')
   await js("document.getElementById('session-grid').scrollTop=0")
   await js("document.querySelector('.session-chip[data-id=api]').click();window.__whale=document.getElementById('focus-avatar');window.__whaleImage=window.__whale.querySelector('.whale-working img')")
   assert.equal(await js("window.__whale.dataset.state"),'working')
   assert.equal(await js("getComputedStyle(window.__whale.querySelector('.whale-working')).display"),'block')
   assert.equal(await js("window.__whaleImage.currentSrc"),'jingle-notch-whale://art/working.webp')
   const workingFrames=await verifyAnimation('#focus-avatar','working')
   await pause(1100)
   assert.equal(await js("window.__whale===document.getElementById('focus-avatar')&&window.__whaleImage===document.querySelector('#focus-avatar .whale-working img')"),true,'Polling should retain the current animation element')
   await writeFile(screenshot.replace(/\.png$/u,'-working.png'),(await win.webContents.capturePage()).toPNG())
   await motion('reduce')
   assert.equal(await js("Array.from(document.querySelectorAll('.whale-raster')).every(image=>image.currentSrc.endsWith('-poster.webp'))"),true,'Reduced motion should select decoded static posters')
   await motion('no-preference')
   assert.equal(await js("Array.from(document.querySelectorAll('.whale-raster')).every(image=>!image.currentSrc.endsWith('-poster.webp'))"),true,'Normal motion should restore the animated images')
   await js("document.querySelector('.session-chip[data-id=smoke]').click();document.getElementById('animation-proof').remove()")
   assert.equal(await js("document.getElementById('focus-avatar').dataset.state"),'attention')
   win.webContents.debugger.detach()
   await writeFile(pointerPath,JSON.stringify({x:-10000,y:-10000}))
   for(let i=0;i<40;i++){if(await js("document.body.dataset.mode==='compact'"))break;await pause(50)}
   assert.equal(await js("document.body.dataset.mode"),'compact','Leaving a hover-opened panel should fold after the grace period')
   assert.equal(win.getBounds().width,289,'Collapsed strip should keep only narrow notch wings')
   await js("document.getElementById('mascot').click()")
   await pause(300)
   assert.equal(win.getBounds().width,615)
   assert.ok(win.getBounds().height<320,'Session overview should be shallow')
   assert.equal(await js("document.querySelectorAll('.session-chip').length"),8)
   await js("document.querySelector('.session-chip[data-id=api]').click();window.jingleNotch.expand(false)")
   await pause(150)
   assert.ok((await fetch(process.argv[2]+'/__smoke/request-web',{method:'POST'})).ok)
   for(let i=0;i<50;i++){if(await js("document.body.dataset.mode==='expanded'&&document.querySelector('.session-chip[aria-pressed=true]').dataset.id==='web'"))break;await pause(50)}
   assert.equal(await js("document.body.dataset.mode"),'expanded')
   assert.equal(await js("document.querySelector('.session-chip[aria-pressed=true]').dataset.id"),'web','A new request should select its originating session')
   assert.equal(await js("document.getElementById('focus-name').textContent"),'web','The focused card should match the selected request')
   await js("window.jingleNotch.expand(false)")
   await pause(100)
   assert.ok((await fetch(process.argv[2]+'/__smoke/withdraw-web',{method:'POST'})).ok)
   await pause(1250)
   assert.equal(await js("document.body.dataset.mode"),'compact','Withdrawing a request should not open the panel again')
   assert.ok((await fetch(process.argv[2]+'/__smoke/finish-api',{method:'POST'})).ok)
   await pause(1100)
   const sessionOrder=await js("Array.from(document.querySelectorAll('.session-chip'),node=>node.dataset.id)")
   assert.ok(sessionOrder.indexOf('api')>sessionOrder.indexOf('tests'),'A completed session should move below running sessions')
   await js("document.getElementById('mascot-secondary').click();document.querySelector('.session-chip[data-id=smoke]').click()")
   await js("document.getElementById('recap-open').click()")
   assert.equal(await js("document.body.dataset.view"),'recap')
   assert.equal(await js("document.getElementById('weekly-recap').textContent.includes('No activity recorded')"),true)
   await js("document.getElementById('recap-done').click()")
   await js("document.getElementById('settings-open').click()")
   await pause(100)
   const settingsShot=await win.webContents.capturePage()
   await writeFile(screenshot.replace(/\.png$/u,'-settings.png'),settingsShot.toPNG())
   await js("document.getElementById('auto-close').value='5';document.getElementById('auto-close').dispatchEvent(new Event('change',{bubbles:true}));")
   for(let i=0;i<40;i++){try{if(JSON.parse(readFileSync(path.join(testDirectory,'dsh-jingle-notch','overlay-preferences.json'),'utf8')).autoCloseSeconds===5)break}catch{}await pause(50)}
   assert.equal(JSON.parse(readFileSync(path.join(testDirectory,'dsh-jingle-notch','overlay-preferences.json'),'utf8')).autoCloseSeconds,5,'Settings should persist on disk')
   await js("document.getElementById('settings-done').click()")
   await writeFile(pointerPath,JSON.stringify({x:display.x+Math.round(display.width/2),y:display.y+10}))
   for(let i=0;i<40;i++){if(await js("document.body.dataset.mode==='expanded'"))break;await pause(50)}
   await js("window.jingleNotch.expand(true)")
   await pause(5600)
   assert.equal(await js("document.body.dataset.mode"),'compact','Five-second auto-close should collapse a clicked panel')
   await writeFile(pointerPath,JSON.stringify({x:-10000,y:-10000}))
   await js("document.getElementById('mascot').click()")
   await js("document.getElementById('focus').click()")
   assert.equal(await js("document.body.textContent.includes('END OF COMPLETE PLAN')"),true)
   await js("window.jingleNotch.expand(true);document.body.classList.add('expanded');window.__form=document.querySelector('#cards form');window.__form.querySelector('button[type=submit]').click();")
   assert.match(await js("window.__form.querySelector('.cq-error').textContent"),/Answer each/)
   await js("window.__form.querySelector('input[type=radio]').click();var checks=window.__form.querySelectorAll('input[type=checkbox]');checks[1].click();checks[3].click();window.__form.querySelectorAll('textarea')[1].value='smoke draft';")
   await pause(1600)
   assert.equal(await js("window.__form === document.querySelector('#cards form') && window.__form.querySelectorAll('textarea')[1].value === 'smoke draft'"),true)
   await js("window.__form.querySelector('textarea').dispatchEvent(new CompositionEvent('compositionstart',{bubbles:true}));document.dispatchEvent(new KeyboardEvent('keydown',{key:'Escape',isComposing:true,bubbles:true}));")
   await pause(100)
   assert.equal(await js("document.body.dataset.mode"),'expanded','Composition Escape should leave the reply open')
   assert.equal(nativeLevel,'floating','Composition should lower the native panel below IME candidates')
   await js("window.__form.querySelector('textarea').dispatchEvent(new CompositionEvent('compositionend',{bubbles:true}))")
   await pause(50)
   assert.equal(nativeLevel,'status','A committed composition without focus should restore notch priority')
   assert.ok((await fetch(process.argv[2]+'/__smoke/request-web',{method:'POST'})).ok)
   await pause(1250)
   assert.equal(await js("document.querySelector('.session-chip[aria-pressed=true]').dataset.id"),'smoke','Incoming requests should preserve an unfinished reply')
   assert.equal(await js("window.__form.querySelectorAll('textarea')[1].value"),'smoke draft')
   assert.ok((await fetch(process.argv[2]+'/__smoke/withdraw-web',{method:'POST'})).ok)
   const preferences=win.webContents.getLastWebPreferences()
   assert.equal(preferences.nodeIntegration,false);assert.equal(preferences.contextIsolation,true);assert.equal(preferences.sandbox,true)
   const dashboard=new BrowserWindow({show:false,webPreferences:{nodeIntegration:false,contextIsolation:true,sandbox:true}})
   await dashboard.loadURL(process.argv[2]+'/jingle')
   const dash=source=>dashboard.webContents.executeJavaScript(source,true)
   for(let i=0;i<100;i++){
    if(await dash("document.querySelectorAll('#alertList form').length === 1"))break
    await pause(100)
   }
   assert.equal(await dash("typeof window.JingleNotchSurface.reconcile"),'function')
   assert.equal(await dash("document.body.textContent.includes('END OF COMPLETE PLAN')"),true)
   await dash("window.__draft=document.querySelector('#alertList form textarea');window.__draft.value='dashboard draft';window.__draft.focus();")
   await pause(1700)
   assert.equal(await dash("window.__draft === document.querySelector('#alertList form textarea') && window.__draft.value === 'dashboard draft' && document.activeElement === window.__draft"),true)
   dashboard.destroy()
   const image=await win.webContents.capturePage()
   await writeFile(screenshot,image.toPNG())
   await js("window.__form.querySelector('button[type=submit]').click();Array.from(document.querySelectorAll('#cards button')).find(b=>b.textContent==='Allow once').click();")
   for(let i=0;i<100;i++){
    if(await js("document.querySelectorAll('#cards .cq-card').length === 0"))break
    await pause(100)
   }
   assert.equal(await js("document.querySelectorAll('#cards .cq-card').length"),0)
   await js("window.__fallbackImage=document.querySelector('.session-chip[data-id=tests] .whale-working img');window.__fallbackImage.src='jingle-notch-whale://art/missing.webp'")
   for(let i=0;i<40;i++){if(await js("window.__fallbackImage.dataset.failed==='true'&&window.__fallbackImage.complete&&window.__fallbackImage.naturalWidth>0"))break;await pause(50)}
   assert.equal(await js("window.__fallbackImage.currentSrc"),'jingle-notch-whale://art/working-poster.webp','A failed animation should recover to its packaged poster')
   await js("window.__fallbackImage.src='jingle-notch-whale://art/missing-again.webp'")
   for(let i=0;i<40;i++){if(await js("window.__fallbackImage.closest('.whale-avatar').dataset.unavailable==='true'"))break;await pause(50)}
   assert.equal(await js("window.__fallbackImage.closest('.whale-avatar').querySelector('.whale-fallback').hidden"),false,'A second image failure should leave a visible whale fallback')
   console.log('SMOKE PASSED '+JSON.stringify({screenshot,bounds:win.getBounds(),notchFrames,secondaryFrames,workingFrames,visibleSessions:4,totalSessions:8,wheelScrolling:true,sessionColors:true,activeSorting:true,requestExpansionAndSelection:true,compositionKeys:true,whaleImagesDecoded:true,reducedMotion:true,animationRetained:true,decodeRecovery:true,isolated:true,fullPlan:true,draftPreserved:true,dashboardCspAndFocus:true,answersDelivered:true}))
   done=true;
   void js("document.getElementById('quit-top').click()").catch(error=>console.log('Renderer released during quit: '+error.message))
  }catch(error){console.error('SMOKE FAILED',error);clearTimeout(deadline);app.exit(1)}
 })
})
const overlayEntry=process.env.JINGLE_NOTCH_SMOKE_PACKAGE?path.join(process.env.JINGLE_NOTCH_SMOKE_PACKAGE,'lib/overlay/main.js'):path.resolve(__dirname,'../../lib/overlay/main.js')
import(pathToFileURL(overlayEntry).href).catch(error=>{console.error(error);app.exit(1)})
app.on('will-quit',()=>{clearTimeout(deadline);if(!done)console.error('SMOKE exited before verification');else console.log('QUIT BUTTON VERIFIED: native application exited')})
